(* [comment removed for export] *)
Definition XKN : list kentry :=
  map (fun c : Z * nat * Z => KWord (SA (ELit 0) (fst (fst c))) (snd (fst c)) (ELit (snd c))) XC9_CELLS
  ++ [KWord (SA (ELit 0) 6791384) 4 (EVar 4); KRange (EVar 4) 1 4194303; KImg 0x1420d0 0x1421c0; KImg 0x1422a8 0x142a10].
